const clean = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();

const safeParse = (value) => {
  if (typeof value !== 'string') return value;
  const t = value.trim();
  if (!(t.startsWith('{') || t.startsWith('['))) return value;
  try {
    return JSON.parse(t);
  } catch {
    return value;
  }
};

const unwrap = (v) => {
  if (v == null) return '';
  if (['string', 'number', 'boolean'].includes(typeof v)) return String(v);
  if (Array.isArray(v)) return v.map(unwrap).filter(Boolean).join(' ');
  if (typeof v === 'object') {
    const preferred = [v.value, v.text, v.subject, v.description_text, v.description, v.body, v.content, v.message];
    for (const item of preferred) {
      const out = unwrap(item);
      if (out) return out;
    }
  }
  return '';
};

const pickFirst = (...vals) => {
  for (const val of vals) {
    const out = clean(unwrap(val));
    if (out) return out;
  }
  return '';
};

const resolveReplyVisibility = (obj) => {
  const raw = pickFirst(
    obj?.replyVisibility,
    obj?.reply_visibility,
    obj?.replyMode,
    obj?.reply_mode,
    obj?.responseVisibility,
    obj?.response_visibility,
    obj?.freshdesk?.replyVisibility,
    obj?.freshdesk?.reply_visibility,
    obj?.ticket?.replyVisibility,
    obj?.ticket?.reply_visibility
  ).toLowerCase();

  const privateSignals = new Set(['private', 'internal', 'note']);
  return privateSignals.has(raw) ? 'private' : 'public';
};

const raw = safeParse($json.body) || safeParse($json.payload) || $json;
const input = typeof raw === 'object' && raw !== null ? raw : $json;

const readEnv = (k) => String($env[k] ?? '').trim();

const readLlmPack = (root) => {
  const llm = root?.llm && typeof root.llm === 'object' ? root.llm : {};
  const pick = (...keys) => {
    for (const k of keys) {
      const v = clean(unwrap(root?.[k] ?? llm?.[k]));
      if (v) return v;
    }
    return '';
  };
  const maxStr = pick('llmOpenapiMaxChars', 'openapiMaxChars') || readEnv('LLM_OPENAPI_MAX_CHARS');
  const maxN = parseInt(maxStr, 10);
  const llmOpenapiMaxChars = Number.isFinite(maxN) && maxN >= 1000 ? Math.min(maxN, 250000) : 12000;

  const llmUserInstructions =
    pick('llmUserInstructions', 'userInstructions', 'USER_INSTRUCTIONS') || readEnv('LLM_USER_INSTRUCTIONS');

  let follow =
    pick('llmFollowUpPrompt', 'followUpQuestions', 'followUpPrompt', 'llmFollowUpQuestions') ||
    readEnv('LLM_FOLLOW_UP_PROMPT') ||
    readEnv('LLM_FOLLOW_UP_QUESTIONS');
  if (Array.isArray(root?.llmFollowUpQuestions)) {
    follow = root.llmFollowUpQuestions.map((x) => clean(String(x))).filter(Boolean).join('\\n');
  } else if (Array.isArray(llm?.followUpQuestions)) {
    follow = llm.followUpQuestions.map((x) => clean(String(x))).filter(Boolean).join('\\n');
  }

  return {
    llmOpenapiMaxChars,
    llmUserInstructions: llmUserInstructions || '',
    llmFollowUpPrompt: follow || ''
  };
};

const llmPack = readLlmPack(input);

const isTelegram = Boolean(input?.message?.chat?.id);

if (isTelegram) {
  const msg = pickFirst(input.message.text, input.message.caption);
  return {
    source: 'telegram',
    chatId: String(input.message.chat.id),
    ticketId: null,
    ticketSubject: null,
    ticketBody: msg,
    analysisText: msg,
    ccEmails: [],
    replyVisibility: resolveReplyVisibility(input),
    ...llmPack
  };
}

const ticket = input.ticket || input.data?.ticket || input.freshdesk_webhook?.ticket || input;

let ticketId = pickFirst(
  ticket?.id,
  ticket?.ticket_id,
  ticket?.display_id,
  input?.ticket_id,
  input?.id,
  input?.display_id,
  input?.data?.ticket_id,
  input?.data?.id,
  input?.ticketId
);

if (!ticketId) {
  const rawText = clean(JSON.stringify(input));
  const m = rawText.match(/"(?:ticket_id|ticketId|id|display_id)"\s*:\s*"?(\\d{2,})"?/i);
  if (m) ticketId = m[1];
}

const subject = pickFirst(ticket?.subject, input?.subject, input?.data?.subject, input?.email_config?.subject);
const description = pickFirst(
  ticket?.description_text,
  ticket?.description,
  ticket?.body,
  ticket?.content,
  input?.description_text,
  input?.description,
  input?.body,
  input?.content,
  input?.message
);

const ccPool = [
  ...(Array.isArray(ticket?.cc_emails) ? ticket.cc_emails : []),
  ...(Array.isArray(input?.cc_emails) ? input.cc_emails : []),
  ...(Array.isArray(input?.data?.cc_emails) ? input.data.cc_emails : []),
  ...(Array.isArray(ticket?.reply_cc_emails) ? ticket.reply_cc_emails : [])
];
const ccEmails = [...new Set(ccPool.map((v) => String(v || '').trim().toLowerCase()).filter(Boolean))];

const fallback = clean(JSON.stringify(input));
const analysisText = clean([subject, description].filter(Boolean).join('\\n\\n')) || fallback;

return {
  source: 'freshdesk',
  chatId: null,
  ticketId: ticketId || null,
  ticketSubject: subject,
  ticketBody: description,
  analysisText,
  ccEmails,
  replyVisibility: resolveReplyVisibility(input),
  ...llmPack
};

const base = $node["Normalize Input"].json;
const rows = Array.isArray($json) ? $json : [];

const stripHtml = (value) => String(value || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<br\s*\/?\s*>/gi, '\n')
  .replace(/<\/p>|<\/div>|<\/li>|<\/tr>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/\s+/g, ' ')
  .trim();
const clip = (v, n) => {
  const t = String(v || '').trim();
  return t.length > n ? `${t.slice(0, n)}...` : t;
};

const conversations = rows
  .map((c, i) => {
    const incoming = Boolean(c?.incoming);
    const privateNote = Boolean(c?.private);
    const role = incoming ? "requester" : (privateNote ? "agent_note" : "agent_reply");
    const body = stripHtml(c?.body_text || c?.body || "");
    if (!body) return null;
    return `Conversation ${i + 1} (${role}): ${body}`;
  })
  .filter(Boolean)
  .join("\n");

const subject = stripHtml(base.ticketSubject || '');
const ticketBodyClean = stripHtml(base.ticketBody || '');

const analysisText = [
  `Subject: ${subject}`,
  `Ticket body: ${ticketBodyClean}`,
  conversations ? `Conversation thread:\n${conversations}` : ""
].filter(Boolean).join("\n\n").trim();

const ragMaxChars = Number($env.RAG_QUERY_MAX_CHARS || 4000);
const analysisTextForRag = clip(analysisText, Number.isFinite(ragMaxChars) && ragMaxChars > 500 ? ragMaxChars : 4000);

return {
  ...base,
  ticketSubject: subject || base.ticketSubject,
  ticketBodyClean,
  conversationText: conversations,
  analysisText,
  analysisTextForRag
};

const base = $json;
const stripHtml = (value) => String(value || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<br\s*\/?\s*>/gi, '\n')
  .replace(/<\/p>|<\/div>|<\/li>|<\/tr>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/\s+/g, ' ')
  .trim();
const clip = (v, n) => {
  const t = String(v || '').trim();
  return t.length > n ? `${t.slice(0, n)}...` : t;
};

const cleaned = stripHtml(base.analysisText || base.ticketBody || '');
const ragMaxChars = Number($env.RAG_QUERY_MAX_CHARS || 4000);

return {
  ...base,
  conversationText: '',
  analysisText: cleaned,
  analysisTextForRag: clip(cleaned, Number.isFinite(ragMaxChars) && ragMaxChars > 500 ? ragMaxChars : 4000)
};

const safeNodeJson = (name) => {
  try {
    return $node[name]?.json || null;
  } catch {
    return null;
  }
};

const fromFreshdesk = safeNodeJson('Build Ticket+Conversation Text');
const fromTelegram = safeNodeJson('Prepare Telegram Analysis Text');
const fromNormalize = safeNodeJson('Normalize Input');

const base = fromFreshdesk || fromTelegram || fromNormalize || {
  source: 'unknown',
  chatId: null,
  ticketId: null,
  ticketSubject: '',
  ticketBody: '',
  analysisText: ''
};

const specObj = $json;
const openapiText = typeof specObj === 'string' ? specObj : JSON.stringify(specObj, null, 2);
const maxChars = Number(base.llmOpenapiMaxChars) || 12000;
const openapiTrunc = openapiText.slice(0, maxChars);

const prompt = [
  'You are an issue analyzer for KwikID / Video KYC style support.',
  'Knowledge in Supabase RAG comes from docs, data/kwikid JSON, Excel SOPs, and Freshdesk history.',
  'Use the support text and OpenAPI spec to classify the issue and propose retrieval + optional fix APIs.',
  'Return ONLY valid JSON with schema:',
  '{"exactIssue":"string","issueSummary":"string","searchQuery":"string","issueCategory":"string","candidateOperations":["operationId or METHOD path"],"requiredParameters":[{"name":"string","in":"query|path|header|body","description":"string"}],"missingFromTicket":["string"],"shouldCallTroubleshootingApi":boolean}',
  '',
  'Rules:',
  '- exactIssue: short precise label (e.g. video_not_available).',
  '- issueSummary: 1-2 sentence technical summary.',
  '- searchQuery: best phrase to retrieve SOP/troubleshooting from vector DB.',
  '- issueCategory: slug for routing (video_not_available, auth, network, other).',
  '- candidateOperations: pick only operations that exist in the OpenAPI excerpt; empty array if none.',
  '- requiredParameters: parameters for the best fix/diagnostic operation; empty if none.',
  '- missingFromTicket: parameter names or facts still required from the client before calling that API; empty if the ticket text already contains them.',
  '- shouldCallTroubleshootingApi: true if a concrete diagnostic/fix operation from the OpenAPI spec applies (set true even when parameters are still missing — list those in missingFromTicket).',
  '',
  'OpenAPI spec (truncated):',
  openapiTrunc,
  '',
  'Support text:',
  base.analysisText || '(No support text available in this partial run)',
  ...(base.llmUserInstructions
    ? ['', 'USER_INSTRUCTIONS (priority; follow strictly):', base.llmUserInstructions]
    : []),
  ...(base.llmFollowUpPrompt
    ? ['', 'Follow-up / clarifying guidance for later LLM replies:', base.llmFollowUpPrompt]
    : [])
].join('\\n');

return {
  ...base,
  prompt
};

const base = $node["Prepare Issue Detection Prompt"].json;
const raw = $json?.output?.[0]?.content?.[0]?.text ?? '';
let text = String(raw).trim();
text = text.replace(/^```[a-zA-Z0-9_-]*\s*/g, '').replace(/```\s*$/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    exactIssue: 'Unclassified support issue',
    issueSummary: base.analysisText.slice(0, 500),
    searchQuery: base.analysisText.slice(0, 300),
    issueCategory: 'other',
    candidateOperations: [],
    requiredParameters: [],
    missingFromTicket: [],
    shouldCallTroubleshootingApi: false,
    fixApiSuggested: false
  };
}

const missingRaw = parsed.missingFromTicket;
const missingArr = Array.isArray(missingRaw)
  ? missingRaw.map((x) => String(x || '').trim()).filter(Boolean)
  : (missingRaw ? [String(missingRaw).trim()] : []);

const ops = parsed.candidateOperations;
const opsArr = Array.isArray(ops) ? ops.map((x) => String(x || '').trim()).filter(Boolean) : [];

const req = parsed.requiredParameters;
const reqArr = Array.isArray(req) ? req : [];

const fixSuggested = Boolean(parsed.shouldCallTroubleshootingApi);
const clean = (v) => String(v || '').replace(/\s+/g, ' ').trim();
const textPool = [base.analysisText, base.ticketSubject, base.ticketBody].map(clean).filter(Boolean).join(' \n ');

const extractMatch = (regex, groupIdx = 0) => {
  const m = textPool.match(regex);
  return m ? String(m[groupIdx] || '').trim() : '';
};

const sessionId = extractMatch(/\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/i);
const pan = extractMatch(/\b[A-Z]{5}\d{4}[A-Z]\b/i).toUpperCase();
const phoneRaw = extractMatch(/(?:\+?91[-\s]?)?([6-9]\d{9})\b/i, 1);
const phoneNumber = phoneRaw ? phoneRaw.slice(-10) : '';
const errorCode = extractMatch(/\b(?:error(?:\s*code)?|err)\s*[:#=-]?\s*([A-Za-z0-9_-]{2,20})\b/i, 1).toUpperCase();
const appVersion = extractMatch(/\b(?:app(?:lication)?\s*version|version|v)\s*[:=\-]?\s*(\d+\.\d+(?:\.\d+)?)\b/i, 1);
const platform = extractMatch(/\b(android|ios|web|portal|desktop)\b/i, 1).toLowerCase();
const eventTimestamp = extractMatch(/\b(\d{4}-\d{2}-\d{2}[t\s]\d{2}:\d{2}(?::\d{2})?)\b/i, 1);

const structuredSignals = {
  sessionId,
  pan,
  phoneNumber,
  errorCode,
  appVersion,
  platform,
  eventTimestamp
};

const structuredSignalText = Object.entries(structuredSignals)
  .filter(([, value]) => clean(value))
  .map(([key, value]) => `${key}:${clean(value)}`)
  .join(' | ');

return {
  ...base,
  exactIssue: String(parsed.exactIssue || 'Unclassified support issue'),
  issueSummary: String(parsed.issueSummary || ''),
  searchQuery: String(parsed.searchQuery || base.analysisText || '').trim(),
  issueCategory: String(parsed.issueCategory || 'other').toLowerCase(),
  candidateOperations: opsArr,
  requiredParameters: reqArr,
  missingFromTicket: missingArr,
  fixApiSuggested: fixSuggested,
  shouldCallTroubleshootingApi: fixSuggested && missingArr.length === 0,
  structuredSignals,
  structuredSignalText
};

const base = $node["Parse Issue Output"].json;
const queryPayload = $json;

const clean = (value) => String(value || '').replace(/\s+/g, ' ').trim();
const trimTo = (value, max = 650) => {
  const text = clean(value);
  return text.length > max ? `${text.slice(0, max)}...` : text;
};
const uniq = (arr) => arr.filter((v, i) => arr.findIndex((x) => String(x).toLowerCase() === String(v).toLowerCase()) === i);
const num = (v, d) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : d;
};
const pickMatches = (payload) => {
  if (Array.isArray(payload?.matches)) return payload.matches;
  if (Array.isArray(payload?.data?.matches)) return payload.data.matches;
  if (Array.isArray(payload?.result?.matches)) return payload.result.matches;
  if (Array.isArray(payload?.documents)) return payload.documents;
  if (Array.isArray(payload)) return payload;
  return [];
};

const isStackUrl = (url) => /stackoverflowteams\.com|stackoverflow\.com\/questions/i.test(String(url || ''));
const isFreshdeskUrl = (url) => {
  const u = String(url || '');
  return /\/a\/tickets\/\d+|\/helpdesk\/tickets\/\d+/i.test(u) || /freshdesk\.com\/a\/tickets\//i.test(u);
};

const stopWords = new Set(['the','and','for','with','from','that','this','have','were','your','you','our','are','not','but','can','cannot','will','into','onto','about','issue','ticket','please']);
const tokenize = (text) => clean(text).toLowerCase().split(/[^a-z0-9]+/).filter((w) => w.length > 2 && !stopWords.has(w));
const focusPhrases = uniq([
  base.exactIssue,
  base.issueCategory,
  base.searchQuery,
  base.issueSummary,
  base.structuredSignalText
].map(clean).filter(Boolean));
const focusTokens = uniq(focusPhrases.flatMap(tokenize)).slice(0, 60);

const extractUrlCandidates = (m) => {
  const meta = m.metadata || {};
  const keys = ['post_link', 'link', 'url', 'ticket_link', 'ticket_url', 'permalink'];
  const out = keys.map((k) => clean(meta[k] || '')).filter(Boolean);
  const content = String(m.content || m.text || m.chunk || m.page_content || '');
  const urlRe = /https?:\/\/[^\s\)\]'"<>]+/g;
  let ma;
  while ((ma = urlRe.exec(content))) out.push(clean(ma[0]));
  return uniq(out);
};

const lexicalSignal = (text, title) => {
  const hay = `${clean(title)} ${clean(text)}`.toLowerCase();
  const tokenHits = focusTokens.reduce((acc, t) => acc + (hay.includes(t) ? 1 : 0), 0);
  const overlapScore = focusTokens.length ? tokenHits / focusTokens.length : 0;
  const phraseHits = focusPhrases.slice(0, 10).reduce((acc, p) => acc + (p && hay.includes(p.toLowerCase()) ? 1 : 0), 0);
  const phraseScore = Math.min(1, phraseHits / 3);
  return { overlapScore, phraseScore };
};

const rawMatches = pickMatches(queryPayload);
const normalized = rawMatches.map((m) => {
  const metadata = m?.metadata || m?.meta || {};
  const content = m?.content || m?.text || m?.chunk || m?.page_content || '';
  const title = metadata?.title || metadata?.heading || metadata?.file_path || metadata?.source || 'Untitled';
  const similarity = Number(m?.similarity ?? m?.score ?? m?.distance ?? 0);
  const st = String(metadata?.source_type || metadata?.source || 'unknown').toLowerCase();
  const wMd = num($env.RAG_WEIGHT_MD, 1.0);
  const wJson = num($env.RAG_WEIGHT_JSON, 1.0);
  const wExcel = num($env.RAG_WEIGHT_EXCEL, 1.0);
  const wFd = num($env.RAG_WEIGHT_FRESHDESK, 1.0);
  const wMap = { md: wMd, mdx: wMd, json: wJson, excel: wExcel, freshdesk: wFd };
  const w = wMap[st] ?? 1.0;
  const effectiveScore = similarity * w;
  const lex = lexicalSignal(content, title);
  const rerankScore = (effectiveScore * 0.65) + (lex.overlapScore * 0.25) + (lex.phraseScore * 0.10);
  return { metadata, content, title, similarity, effectiveScore, overlapScore: lex.overlapScore, phraseScore: lex.phraseScore, rerankScore };
});

normalized.sort((a, b) => b.rerankScore - a.rerankScore);

const top = normalized.filter((m) => clean(m.content)).slice(0, 5);
const sims = top.map((m) => Number(m?.similarity ?? 0));
const rerankScores = top.map((m) => Number(m?.rerankScore ?? 0));
const topSimilarity = sims.length ? Math.max(...sims) : 0;
const topRerankScore = rerankScores.length ? Math.max(...rerankScores) : 0;
const confidenceScore = top.length ? ((topSimilarity * 0.55) + (topRerankScore * 0.45)) : 0;

const insufficient_context = Boolean(queryPayload?.insufficient_context);
const queryClarification = clean(queryPayload?.clarification || '');
const queryDiagnostics = queryPayload?.diagnostics || {};

const context = top.map((m, i) => {
  const sourceType = m.metadata?.source_type || m.metadata?.source || 'unknown';
  const postLink = clean(m.metadata?.post_link || m.metadata?.link || m.metadata?.url || '');
  const ticketLink = clean(m.metadata?.ticket_link || m.metadata?.ticket_url || '');
  return [
    `Result ${i + 1}`,
    `score=${Number(m?.similarity ?? 0).toFixed(3)} effective=${Number(m?.effectiveScore ?? 0).toFixed(3)} rerank=${Number(m?.rerankScore ?? 0).toFixed(3)}`,
    `source_type=${sourceType}`,
    `title=${m.title}`,
    postLink ? `post_link=${postLink}` : '',
    ticketLink ? `ticket_link=${ticketLink}` : '',
    `content=${trimTo(m.content, 650)}`
  ].filter(Boolean).join('\\n');
}).join('\\n\\n---\\n\\n');

const stackPostUrls = uniq(top.flatMap((m) => extractUrlCandidates(m).filter((u) => isStackUrl(u))));
const freshdeskUrls = uniq(top.flatMap((m) => extractUrlCandidates(m).filter((u) => isFreshdeskUrl(u))));

const referenceResults = top.map((m, i) => ({
  result: i + 1,
  score: Number(m?.similarity ?? 0),
  effectiveScore: Number(m?.effectiveScore ?? 0),
  rerankScore: Number(m?.rerankScore ?? 0),
  sourceType: m.metadata?.source_type || m.metadata?.source || 'unknown',
  title: m.title,
  postLink: clean(m.metadata?.post_link || m.metadata?.link || m.metadata?.url || ''),
  ticketLink: clean(m.metadata?.ticket_link || m.metadata?.ticket_url || ''),
  excerpt: trimTo(m.content, 280)
}));

const text = String(base.analysisText || '').toLowerCase();
const issueCategory = String(base.issueCategory || 'other').toLowerCase();
const hasSessionId = Boolean(clean(base?.structuredSignals?.sessionId)) || /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i.test(text);
const hasSymptomKeywords = /(error|failed|failure|not working|issue|problem|unable|can't|cannot|blank|black screen|stuck|timeout|otp|crash|reject|decline)/i.test(text);
const looksLikeInformationalOnly = /(test call|call done|session id|agent portal)/i.test(text);

const aiMissing = Array.isArray(base.missingFromTicket)
  ? base.missingFromTicket.map((x) => String(x || '').trim()).filter(Boolean)
  : [];

const baseThreshold = num($env.SOP_MIN_SIMILARITY, 0.2);
const categoryThresholdMap = {
  auth: Math.max(baseThreshold, 0.32),
  video_not_available: Math.max(baseThreshold, 0.30),
  network: Math.max(baseThreshold, 0.28),
  other: Math.max(baseThreshold, 0.24)
};
const categoryThreshold = categoryThresholdMap[issueCategory] || Math.max(baseThreshold, 0.26);
const hasActionableEvidence = top.length >= 2 && confidenceScore >= categoryThreshold;

const structured = base.structuredSignals || {};
const missingCriticalSignals = [];
if (issueCategory === 'video_not_available' && !clean(structured.sessionId)) missingCriticalSignals.push('sessionId');
if (issueCategory === 'auth' && !clean(structured.phoneNumber) && !clean(structured.pan)) missingCriticalSignals.push('phoneNumber_or_pan');
if (issueCategory === 'network' && !clean(structured.appVersion) && !clean(structured.platform)) missingCriticalSignals.push('appVersion_or_platform');

const needsClarification = Boolean(
  insufficient_context ||
  aiMissing.length > 0 ||
  missingCriticalSignals.length > 0 ||
  !hasActionableEvidence ||
  (looksLikeInformationalOnly && !hasSymptomKeywords) ||
  (hasSessionId && !hasSymptomKeywords)
);

const missingFromTicketHints = uniq([
  ...aiMissing,
  ...missingCriticalSignals
].map((q) => String(q || '').trim()).filter(Boolean)).slice(0, 8);

let needsClarificationReason = '';
if (needsClarification) {
  if (insufficient_context && queryClarification) needsClarificationReason = queryClarification;
  else if (insufficient_context) needsClarificationReason = 'Backend confidence gate (insufficient_context) — narrow query or add ticket details.';
  else if (!hasActionableEvidence) needsClarificationReason = `Top evidence confidence (${confidenceScore.toFixed(3)}) is below category threshold (${categoryThreshold.toFixed(3)}).`;
  else if (missingCriticalSignals.length) needsClarificationReason = `Critical diagnostic fields missing: ${missingCriticalSignals.join(', ')}.`;
  else needsClarificationReason = 'Ticket content does not include a clear symptom/root issue from client side.';
}

return {
  ...base,
  ragContext: context,
  relevantTroubleshootingContext: context,
  hasContext: top.length > 0,
  ragCount: top.length,
  topSimilarity,
  topRerankScore,
  confidenceScore,
  categoryThreshold,
  ragSampleTitles: top.map((m) => m.title).slice(0, 3),
  stackPostUrls,
  freshdeskUrls,
  referenceResults,
  insufficient_context,
  queryClarification,
  queryDiagnostics,
  needsClarification,
  needsClarificationReason,
  missingFromTicketHints,
  rerankDiagnostics: {
    focusPhrases: focusPhrases.slice(0, 8),
    focusTokenCount: focusTokens.length,
    hasActionableEvidence
  }
};

const base = $json;
const ack = 'Thank you for contacting support. We could not match this issue to an automated playbook with enough confidence. Our team has been notified and will follow up shortly.';
const data = {
  name: `[Support] ${base.exactIssue || 'Escalation'} — ${base.ticketId ? 'FD #' + base.ticketId : 'Telegram ' + (base.chatId || '')}`,
  notes: [
