  ].join('\\n')
};
return { ...base, noSopAckMessage: ack, asanaTaskData: data };

const b = $json;
const data = { ...b.asanaTaskData };
const proj = String($env.ASANA_PROJECT_GID || '').trim();
const ws = String($env.ASANA_WORKSPACE_GID || '').trim();
if (proj) data.projects = [proj];
else if (ws) data.workspace = ws;
