const base = $node["Build Supabase Context"].json;
const rawResponse = $node["First Response (OpenAPI + RAG)"]?.json?.output?.[0]?.content?.[0]?.text || '';
const firstResponse = String(rawResponse || '').trim();

const clean = (v) => String(v ?? '').replace(/\s+/g, ' ').trim();
const pick = (...vals) => {
  for (const v of vals) {
    const out = clean(v);
    if (out) return out;
  }
  return '';
};

const toTitleCase = (value) => clean(value)
  .toLowerCase()
  .split(' ')
  .filter(Boolean)
  .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
  .join(' ');

const allowedPriority = new Set(['Low', 'Medium', 'High', 'Urgent']);
const allowedSource = new Set(['Email', 'Portal', 'Phone', 'Outbound Email']);
const allowedType = new Set(['Issues', 'Login', 'P1', 'BA BAU', 'Feedback', 'Internal mail']);
const allowedEnvironment = new Set(['Production', 'UAT', 'Other']);
const allowedIssueArea = new Set(['API', 'Backend', 'Database', 'DevOps/infrastructure/deployments', 'Frontend', 'Network/firewall', 'Other', 'Third-party Integrations']);
const allowedPortal = new Set(['Admin', 'Agent', 'Agentless', 'Auditor', 'Other', 'SaaS', 'Server', 'User']);

const normalizedSource = (() => {
  const src = clean(base.source).toLowerCase();
  if (src === 'freshdesk') return 'Email';
  if (src === 'telegram') return 'Portal';
  return null;
})();

const normalizedPriority = (() => {
  const p = toTitleCase(base.priority || '');
  return allowedPriority.has(p) ? p : 'Medium';
})();

const normalizedType = (() => {
  const t = pick(base.type, base.issueCategory === 'auth' ? 'Login' : 'Issues');
  return allowedType.has(t) ? t : 'Issues';
})();

const normalizedEnvironment = (() => {
  const env = toTitleCase(base.environment || '');
  return allowedEnvironment.has(env) ? env : null;
})();

const normalizedIssueArea = (() => {
  const raw = clean(base.issueArea || base.issue_category || base.issueCategory || '').toLowerCase();
  if (raw.includes('api')) return 'API';
  if (raw.includes('backend')) return 'Backend';
  if (raw.includes('database') || raw.includes('db')) return 'Database';
  if (raw.includes('frontend') || raw.includes('ui')) return 'Frontend';
  if (raw.includes('network') || raw.includes('firewall')) return 'Network/firewall';
  if (raw.includes('devops') || raw.includes('infra') || raw.includes('deploy')) return 'DevOps/infrastructure/deployments';
  if (raw.includes('integration') || raw.includes('third-party') || raw.includes('third party')) return 'Third-party Integrations';
  return null;
})();

const normalizedPortal = (() => {
  const p = toTitleCase(base.portal || '');
  return allowedPortal.has(p) ? p : null;
})();

const queryType = pick(base.query_type, base.queryType, base.exactIssue, base.issueCategory) || null;
const summary = pick(base.issueSummary, base.exactIssue, base.ticketBody, 'No Summary');

const tags = [
  clean(base.issueCategory),
  ...(Array.isArray(base.missingFromTicketHints) ? base.missingFromTicketHints.map(clean) : []),
  ...(Array.isArray(base.stackPostUrls) && base.stackPostUrls.length ? ['rag_context'] : [])
].map((t) => t.toLowerCase()).filter(Boolean);
const uniqueTags = [...new Set(tags)].slice(0, 12);

const dueByTime = (() => {
  const d = clean(base.due_by_time || base.dueByTime || '');
  if (/^\d{4}-\d{2}-\d{2}(?:\s\d{2}:\d{2}:\d{2})?$/.test(d)) return d.length === 10 ? `${d} 00:00:00` : d;
  return null;
})();

const freshdeskAutofill = {
  ticket_id: base.ticketId ? Number(base.ticketId) : null,
  subject: pick(base.ticketSubject, base.exactIssue, 'Support request'),
  status: 'Open',
  priority: normalizedPriority,
  source: allowedSource.has(normalizedSource || '') ? normalizedSource : 'Email',
  type: normalizedType,
  agent: null,
  group: null,
  tags: uniqueTags,
  clients: pick(base.clients, base.client, base.company_name, base.companyName) || null,
  query_type: queryType,
  environment: normalizedEnvironment,
  issue_area: allowedIssueArea.has(normalizedIssueArea || '') ? normalizedIssueArea : null,
  portal: normalizedPortal,
  impact: null,
  summary,
  contact_full_name: pick(base.contact_full_name, base.contactName, base.requesterName) || null,
  contact_email: pick(base.contact_email, base.requesterEmail) || null,
  contact_mobile_phone: pick(base.contact_mobile_phone, base.requesterPhone) || null,
  company_name: pick(base.company_name, base.companyName) || null,
  due_by_time: dueByTime
};

return {
  ...base,
  firstResponse,
  freshdeskAutofill,
  responseDiagnostics: {
    hasResponse: Boolean(firstResponse),
    responseLength: firstResponse.length,
    confidenceScore: Number(base.confidenceScore || 0),
    hasContext: Boolean(base.hasContext),
    needsClarification: Boolean(base.needsClarification),
    hasFreshdeskAutofill: true
  }
};

const base = $node["Prepare QA Assessment Prompt"].json;
const raw =
  $node["QA Assessment (First Response)"]?.json?.output?.[0]?.content?.[0]?.text || "";
let text = String(raw).trim();
const fence = String.fromCharCode(96) + String.fromCharCode(96) + String.fromCharCode(96);
if (text.startsWith(fence)) {
  text = text.replace(new RegExp("^" + fence + "(?:json)?\\s*", "i"), "").replace(new RegExp("\\s*" + fence + "$", "i"), "").trim();
}
let qa = {};
try {
  qa = JSON.parse(text);
} catch (e) {
  qa = {
    overall: "needs_human",
    score_0_to_100: 0,
    checklist: {},
    top_issues: ["qa_json_parse_failed"],
    suggested_fixes: [String(e)],
    safe_to_send_as_public_reply: false,
  };
}

const checklist = qa.checklist || {};
const anyFail = Object.values(checklist).some(
  (x) => x && String(x.status || "").toLowerCase() === "fail"
);
const overall = String(qa.overall || "").toLowerCase();
const safe = Boolean(qa.safe_to_send_as_public_reply);
const qaNeedsRegenerate =
  overall === "fail" ||
  overall === "needs_human" ||
  !safe ||
  anyFail;

const firstResponseBeforeQA = String(base.firstResponse || "").trim();

return {
  ...base,
  qaAssessment: qa,
  firstResponseBeforeQA,
  qaNeedsRegenerate,
  qaPass: !qaNeedsRegenerate,
  qaRegenerated: false,
  qaReviewPrivateNote: "",
};

const parsed = $node["Parse QA Assessment"].json;
const rawResponse =
  $node["First Response After QA"]?.json?.output?.[0]?.content?.[0]?.text || "";
const regenerated = String(rawResponse).trim();

const qa = parsed.qaAssessment || {};
const qaNote = [
