  "Top issues: " + (qa.top_issues || []).join("; "),
  "Suggested fixes: " + (qa.suggested_fixes || []).join("; "),
  "",
  "Checklist:",
  JSON.stringify(qa.checklist || {}, null, 2),
  "",
  "Original draft (excerpt):",
  String(parsed.firstResponseBeforeQA || "").slice(0, 2500),
].join("\\n");

return {
  ...parsed,
