  qaReviewPrivateNote: qaNote,
};

const b = $json || {};
if (String(b.source || '').toLowerCase() === 'freshdesk') {
  return {
    ...b,
    firstResponseVisibility: 'public',
    replyVisibility: 'public'
  };
}
return b;

const base = $node['Route Troubleshooting']?.json || {};
const tokenResp = $json;

const tokenKeys = ['token', 'Token', 'access_token', 'accessToken', 'jwt', 'auth_token', 'authToken'];
const pickFrom = (obj) => tokenKeys.map((k) => obj?.[k]).find((v) => v != null && String(v).trim() !== '');

const pickToken = (obj) => {
  if (!obj || typeof obj !== 'object') return '';
  const direct = pickFrom(obj);
  if (direct) return String(direct);
  if (obj.data && typeof obj.data === 'object') {
    const nested = pickFrom(obj.data);
    if (nested) return String(nested);
  }
  for (const value of Object.values(obj)) {
    if (value && typeof value === 'object') {
      const deep = pickFrom(value);
      if (deep) return String(deep);
    }
  }
  return '';
};

const token = pickToken(tokenResp);
if (!token) {
  throw new Error('Unity token generation succeeded but token was not present in response.');
}

return {
  ...base,
  unityAuthToken: token,
  unitySendLinkPayload: base.unitySendLinkPayload || {}
};

const base = $node['After QA Unify'].json;
const route = $node['Route Troubleshooting']?.json || {};
const raw = $json;

const tokenKeys = ['token', 'Token', 'access_token', 'accessToken', 'jwt', 'auth_token', 'authToken'];
const pickFrom = (obj) => tokenKeys.map((k) => obj?.[k]).find((v) => v != null && String(v).trim() !== '');

const pickToken = (obj) => {
  if (!obj || typeof obj !== 'object') return '';
  const direct = pickFrom(obj);
  if (direct) return String(direct);
  if (obj.data && typeof obj.data === 'object') {
    const nested = pickFrom(obj.data);
    if (nested) return String(nested);
  }
  for (const value of Object.values(obj)) {
    if (value && typeof value === 'object') {
      const deep = pickFrom(value);
      if (deep) return String(deep);
    }
  }
  return '';
};

let snippet = '';
try {
  snippet = typeof raw === 'object' ? JSON.stringify(raw).slice(0, 2000) : String(raw).slice(0, 2000);
} catch (e) {
  snippet = String(raw);
}

if (route.apiAutomationName === 'unity_generate_token') {
  const token = pickToken(raw);
  const tokenLine = token ? `Unity token: ${token}` : `Unity token API response: ${snippet}`;
  return {
    ...base,
    firstResponse: `${base.firstResponse}\n\n---\nUnity API automation:\n${tokenLine}`
  };
}

if (route.apiAutomationName === 'unity_old_prod_sendlink') {
  const link = raw?.data?.link || raw?.link || raw?.url || raw?.data?.url || '';
  const traceId = raw?.data?.traceId || raw?.traceId || route?.unitySendLinkPayload?.traceId || '';
  const status = raw?.status || raw?.message || raw?.data?.message || 'received';
  const productCode = route?.unitySendLinkPayload?.extras?.product_code || 'UNKNOWN';
  const details = [
    `Status: ${String(status)}`,
