};

const b = $json;
const channel = b.source === 'freshdesk' ? 'freshdesk' : 'telegram';
const ext = b.source === 'freshdesk' ? String(b.ticketId || '') : String(b.chatId || '');
const pending = (b.missingFieldsList || []).map((p) => ({ param: String(p), asked: false }));
return {
