    pending_questions: pending,
    updated_at: new Date().toISOString()
  })
};

// Upsert HTTP node outputs only Supabase response - ticketId/source are lost. Restore from upstream.
const upstream = $node['Prepare Session Upsert']?.json || {};
const b = { ...upstream, ...($json && typeof $json === 'object' ? $json : {}) };
const lines = (b.missingFieldsList || []).map((x) => `- ${String(x)}`);
const msg = ['To run automated diagnostics, please provide:', ...lines, '', 'Reply with the requested details.'].join('\n');
return { ...b, askClientMessage: msg };

const base = $node['After QA Unify'].json;

const llmMissing = Array.isArray(base.missingFromTicket)
  ? base.missingFromTicket.map((x) => String(x || '').trim()).filter(Boolean)
  : [];

const requestTextRaw = [
  base.analysisText,
  base.searchQuery,
  base.exactIssue,
  base.issueSummary,
  base.ticketSubject,
  base.ticketBody
].map((v) => String(v || '')).join(' ');

const normalizeField = (value) => String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const lowerText = requestTextRaw.toLowerCase();

const parseJsonObject = (v) => {
  if (!v) return null;
  if (typeof v === 'object') return v;
  if (typeof v === 'string') {
    const t = v.trim();
    if (!t) return null;
    if (t.startsWith('{') || t.startsWith('[')) {
      try { return JSON.parse(t); } catch { return null; }
    }
  }
  return null;
};

const nested = (obj, path) => {
  try {
    return path.split('.').reduce((acc, key) => (acc && acc[key] !== undefined ? acc[key] : undefined), obj);
  } catch {
    return undefined;
  }
};

const vkycRawCandidates = [
  base.vkycData,
  base.vkyc,
  base.sessionData,
  base.unityVkyc,
  base.unitySession,
  base.apiResponse,
  base.troubleshootingApiResponse,
  base.raw,
  base.payload,
  base.data
].map(parseJsonObject).filter(Boolean);

const vkycEnvelope = vkycRawCandidates.find((o) => o && typeof o === 'object') || null;
const vkycData = (vkycEnvelope && parseJsonObject(vkycEnvelope.data)) || vkycEnvelope || null;

const present = (v) => v != null && String(v).trim() !== '';

const hasFieldValue = (fieldName) => {
  const key = normalizeField(fieldName);
  if (!key) return true;

  if (vkycData) {
    if (/sessionid/.test(key) && (present(vkycData.session_id) || present(vkycData.audit_id))) return true;
    if (/(userid|customerid|mobileno|mobilenumber|phone|phonenumber)/.test(key) && (present(vkycData.user_id) || present(vkycData.phone_number))) return true;
    if (/auditid/.test(key) && present(vkycData.audit_id)) return true;
    if (/linkid/.test(key) && present(vkycData.link_id)) return true;
    if (/(pan|pannumber)/.test(key) && (present(vkycData.pan_number) || present(nested(vkycData, 'data.pan_number')))) return true;
    if (/aadhaar/.test(key) && (present(vkycData.aadhaar_xml) || present(vkycData.aadhaarpdf_url) || present(vkycData.aadhaar_processing_status))) return true;
    if (/agent/.test(key) && present(vkycData.agent_id)) return true;
    if (/auditor/.test(key) && present(vkycData.auditor_name)) return true;
    if (/(summarypdf|summarypdfurl)/.test(key) && present(vkycData.summary_pdf_url)) return true;
    if (/(summaryjson|summaryjsonurl)/.test(key) && present(vkycData.summary_json_url)) return true;
    if (/zipurl/.test(key) && present(vkycData.zip_url)) return true;
    if (/(uservideo|customervideo)/.test(key) && present(vkycData.user_video_url)) return true;
    if (/(agentvideo|screen|screenshare)/.test(key) && (present(vkycData.agent_video_url) || present(vkycData.agent_screen_url))) return true;
    if (/status/.test(key) && (present(vkycData.session_status) || present(vkycData.aadhaar_processing_status))) return true;
  }

  if (/(urn|urnlist|urns)/.test(key)) {
    return /\b20\d{14}\b/.test(requestTextRaw);
  }

  if (/statuslink|pendingstatus|waitingstatus|callbacklink/.test(key)) {
    return /https?:\/\//i.test(requestTextRaw);
  }

  const parts = String(fieldName || '').toLowerCase().split(/[^a-z0-9]+/).filter((p) => p.length > 2);
  if (!parts.length) return false;
  return parts.every((p) => lowerText.includes(p));
};

const missing = llmMissing.filter((field) => !hasFieldValue(field));

const suggested = Boolean(base.fixApiSuggested);
const fixUrl = String($env.KWIK_FIX_API_URL || '').trim();

let toolRoute = 'normal';
let apiRequestMethod = null;
let apiRequestUrl = null;
let apiRequestBody = null;

if (suggested && missing.length === 0 && fixUrl) {
  toolRoute = 'call_api';
  apiRequestMethod = 'POST';
  apiRequestUrl = fixUrl;
  apiRequestBody = {
    issueCategory: base.issueCategory,
    exactIssue: base.exactIssue,
    ticketId: base.ticketId,
    chatId: base.chatId,
    source: base.source,
    candidateOperations: base.candidateOperations
  };
} else if (suggested && missing.length > 0) {
  toolRoute = 'ask_fields';
}

return {
  ...base,
  toolRoute,
  missingFieldsList: missing,
  detectedVkycContext: Boolean(vkycData),
  apiAutomationName: null,
  apiRequestMethod,
  apiRequestUrl,
  apiRequestBody
};

