const prep = $node["Prepare Troubleshooting Prompt"].json;
const text = [prep.issueCategory, prep.exactIssue, prep.ticketSubject, prep.issueSummary, prep.analysisText].filter(Boolean).join('\n').toLowerCase();

const defaultMap = { rbl: { slug: 'rbl', monitorKeywords: ['rbl'] } };
let configured = defaultMap;
const rawMap = String($env.UPTIME_KUMA_GROUP_MAP_JSON || '').trim();
if (rawMap) { try { const parsed = JSON.parse(rawMap); if (parsed && typeof parsed === 'object') configured = parsed; } catch {} }

const matchedKey = Object.keys(configured).find((k) => text.includes(String(k).toLowerCase())) || '';
const match = matchedKey ? configured[matchedKey] : null;
const baseUrl = String($env.UPTIME_KUMA_BASE_URL || 'http://status.getkwikid.com:3001').replace(/\/+$/, '');
const slug = String(match?.slug || $env.UPTIME_KUMA_DEFAULT_SLUG || '').trim();
const monitorKeywords = Array.isArray(match?.monitorKeywords) ? match.monitorKeywords.map((v) => String(v).toLowerCase()) : [];
const statusPageUrl = slug ? `${baseUrl}/status/${slug}` : '';

return { ...prep, kuma: { matchedKey: matchedKey || null, shouldCheck: Boolean(slug), baseUrl, slug, monitorKeywords, statusPageUrl, summaryUrl: slug ? `${baseUrl}/api/status-page/${slug}` : '', heartbeatUrl: slug ? `${baseUrl}/api/status-page/heartbeat/${slug}` : '' } };

const aiText = String($node["Generate Troubleshooting Steps"].json.output?.[0]?.content?.[0]?.text || '').trim();
const prep = $node["Prepare Troubleshooting Prompt"].json;
const kumaPlan = $node["Build Uptime Kuma Check Plan"].json.kuma || {};

const safeNodeJson = (nodeName) => {
  try {
    const items = $items(nodeName, 0, 0);
    if (Array.isArray(items) && items[0] && typeof items[0] === 'object') {
      return items[0].json || {};
    }
  } catch (e) {
    // Node may be skipped by branch routing; treat as empty payload.
  }
  return {};
};

const summaryPayload = safeNodeJson('Fetch Uptime Kuma Summary');
const heartbeatPayload = safeNodeJson('Fetch Uptime Kuma Heartbeats');

const toArray = (v) => Array.isArray(v) ? v : [];
const toIso = (v) => { if (!v) return ''; const n = Number(v); const d = Number.isFinite(n) && n > 1000000000 ? new Date(n) : new Date(v); if (Number.isNaN(d.getTime())) return ''; return d.toISOString(); };

const monitors = toArray(summaryPayload.publicGroupList || summaryPayload.monitorList || summaryPayload.monitors || summaryPayload.data?.monitors);
const hbByMonitor = heartbeatPayload.heartbeatList || heartbeatPayload.heartbeats || heartbeatPayload.data || {};
const kw = toArray(kumaPlan.monitorKeywords).map((x) => String(x).toLowerCase());
const filtered = monitors.filter((m) => { if (!kw.length) return true; const name = String(m?.name || m?.title || '').toLowerCase(); return kw.some((k) => name.includes(k)); });

const rows = filtered.map((m) => {
  const id = String(m?.id ?? m?.monitorID ?? '');
  const name = String(m?.name || m?.title || `Monitor ${id}`);
  const status = Number(m?.status);
  const state = status === 1 ? 'UP' : (status === 0 ? 'DOWN' : 'UNKNOWN');
  const list = toArray(hbByMonitor[id]);
  let downFrom = ''; let downTo = '';
  if (list.length) {
    for (let i = list.length - 1; i >= 0; i--) {
      const b = list[i];
      if (Number(b?.status) === 0) {
        downTo = toIso(b?.time || b?.timestamp || b?.date);
        let j = i; while (j >= 0 && Number(list[j]?.status) === 0) j--;
        downFrom = toIso(list[j + 1]?.time || list[j + 1]?.timestamp || list[j + 1]?.date);
        break;
      }
    }
  }
  return { name, state, downFrom, downTo };
});

const hasDown = rows.some((r) => r.state === 'DOWN');
const screenshotUrl = kumaPlan.statusPageUrl ? `https://image.thum.io/get/fullpage/${encodeURIComponent(kumaPlan.statusPageUrl)}` : '';

const statusHtml = !kumaPlan.shouldCheck
  ? '<p><strong>Uptime Kuma Check</strong>: skipped (no matching group/slug)</p>'
  : `<p><strong>Uptime Kuma Group</strong>: ${kumaPlan.matchedKey || kumaPlan.slug}</p><p><strong>Status Page</strong>: ${kumaPlan.statusPageUrl ? `<a href="${kumaPlan.statusPageUrl}">${kumaPlan.statusPageUrl}</a>` : 'n/a'}</p><p><strong>Servers Checked</strong>: ${rows.length}</p>` + (rows.length ? `<ul>${rows.map((r) => `<li><strong>${r.name}</strong>: ${r.state}${r.downFrom ? ` | down from ${r.downFrom}` : ''}${r.downTo ? ` to ${r.downTo}` : ''}</li>`).join('')}</ul>` : '<p>No monitor data returned.</p>') + (hasDown && screenshotUrl ? `<p><strong>Screenshot (status page)</strong>: <a href="${screenshotUrl}">${screenshotUrl}</a></p><p><img src="${screenshotUrl}" alt="Uptime Kuma status screenshot" /></p>` : '<p>No servers are currently down.</p>');

const qaRaw = String(prep.qaReviewPrivateNote || '').trim();
const esc = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const qaBlock = qaRaw
  ? `<div style=\"border-left:3px solid #a33;padding:8px;margin-bottom:14px;background:#fff8f8\"><p><strong>QA review</strong></p><pre style=\"white-space:pre-wrap;font-family:system-ui,sans-serif\">${esc(qaRaw)}</pre></div>`
  : '';

const privateNoteHtml = qaBlock + `<div><p><strong>AI Troubleshooting (internal)</strong></p><p>${aiText.replace(/\n/g, '<br/>') || 'No troubleshooting text generated.'}</p><hr/><p><strong>Relevant Stack Post URLs</strong></p><p>${(toArray(prep.stackPostUrls).map((u) => `<a href="${u}">${u}</a>`).join('<br/>') || 'None')}</p><p><strong>Relevant Freshdesk URLs</strong></p><p>${(toArray(prep.freshdeskUrls).map((u) => `<a href="${u}">${u}</a>`).join('<br/>') || 'None')}</p><hr/>${statusHtml}</div>`;

return { ...$node["Generate Troubleshooting Steps"].json, privateNoteHtml, kumaSummary: rows, kumaHasDown: hasDown };
